  "claims": [
    {
      "claim": "Chrysin, a polyphenolic flavone, has measured oral bioavailability <1% in healthy volunteers (C02) and predicted absolute bioavailability 0.003–0.02% in humans (C16), demonstrating very low F for a related phenolic natural product.",
      "card_ids": ["C02", "C16"]
    },
    {
      "claim": "Curcumin is consistently reported to have poor/low oral bioavailability in humans and rodents (C07, C13, C14, C19), supporting a low-F pattern for polyphenolic natural products.",
      "card_ids": ["C07", "C13", "C14", "C19"]
    },
    {
      "claim": "Anthocyanin glycosides (peonidin and petunidin) show fractional bioavailability of only 0.14–0.48% in humans (C01, C03, C04, C05, C10, C11, C12, C17), and flavonolignans show very low oral bioavailability based on high apparent oral clearance (C18, C15, C08, C06, C09).",
      "card_ids": ["C01", "C03", "C04", "C05", "C10", "C11", "C12", "C17", "C18", "C15", "C08", "C06", "C09"]
    },
    {
      "claim": "Scopoletin shares the phenolic and aromatic natural-product features of these low-F compounds; the high transfer likelihood of these contexts supports applying the low-F direction despite its smaller size and better solubility.",
      "card_ids": ["C02", "C07", "C16", "C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": [
        "C01", "C02", "C03", "C04", "C05", "C06", "C07", "C08", "C09",
        "C10", "C11", "C12", "C13", "C14", "C15", "C16", "C17", "C18", "C19"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct scopoletin-specific oral bioavailability or pharmacokinetic record is available; prediction relies on transfer from related polyphenols.",
    "Scopoletin's smaller size and better solubility than chrysin/curcumin/silybin could improve F, but the extent is unknown.",
    "First-pass glucuronidation/sulfation of the phenolic OH is inferred, not directly measured for scopoletin."
  ],
  "decision_summary": "The consistent very low oral bioavailability of structurally related polyphenolic natural products (chrysin, curcumin, anthocyanins, flavonolignans) and the high transfer likelihood of these contexts support F < 20% for scopoletin, despite favorable physicochemical priors."
}

